/**
 * COR-2770: a `collapseBelow` other than 640px brings the phone form in a `<style>` of its own,
 * generated by `phoneFormStyle`. These hold that CSS to the rules `breadcrumbs.css` gives the
 * default 640px, so the two can never draw different phone forms.
 */
import { describe, expect, test } from 'bun:test';

import { parse } from 'postcss';

import { phoneFormStyle } from './breadcrumbs-phone-form.ts';

const stylesheet = await Bun.file(new URL('./breadcrumbs.css', import.meta.url)).text();

/** Each rule inside the media query `params`, as its selector (scope removed) and declarations. */
function phoneRules(css: string, params: string, scope: string): [string, [string, string][]][] {
  const rules: [string, [string, string][]][] = [];
  parse(css).walkAtRules('media', (media) => {
    if (media.params !== params) return;
    media.walkRules((rule) => {
      const selector = rule.selector.replace(/\s+/g, ' ').trim();
      expect(selector.startsWith(scope)).toBe(true);
      const declarations: [string, string][] = [];
      rule.walkDecls(
        (declaration) => void declarations.push([declaration.prop, declaration.value]),
      );
      rules.push([selector.slice(scope.length), declarations]);
    });
  });
  return rules;
}

describe('Breadcrumbs phone form for another collapseBelow', () => {
  test('uses that length in its query and its selector, in the component layer', () => {
    const css = phoneFormStyle('48rem');
    const layers: string[] = [];
    const queries: string[] = [];
    parse(css).walkAtRules('layer', (rule) => void layers.push(rule.params));
    parse(css).walkAtRules('media', (rule) => void queries.push(rule.params));

    expect(layers).toEqual(['cinder.components']);
    expect(queries).toEqual(['not all and (min-width: 48rem)']);
    expect(
      phoneRules(
        css,
        'not all and (min-width: 48rem)',
        '.cinder-breadcrumbs[data-cinder-phone-below="48rem"]',
      ).length,
    ).toBeGreaterThan(0);
    // Server rendering escapes `<` in a style element's text, so the CSS has none.
    expect(css).not.toContain('<');
  });

  test('draws exactly the phone form breadcrumbs.css draws for 640px', () => {
    const fromStylesheet = phoneRules(
      stylesheet,
      '(width < 640px)',
      ".cinder-breadcrumbs[data-cinder-phone-below='640px']",
    );
    const generated = phoneRules(
      phoneFormStyle('640px'),
      'not all and (min-width: 640px)',
      '.cinder-breadcrumbs[data-cinder-phone-below="640px"]',
    );

    expect(fromStylesheet.length).toBe(5);
    expect(generated).toEqual(fromStylesheet);
  });
});
